// ───────── new20_e5_kokugo_12 方角の四字熟語 ─────────
const compass = (x: number, y: number, r = 44): ReturnType<typeof bx>[] => {
  const els: ReturnType<typeof bx>[] = [ci(x, y, 8, '', C.main, FILL.warm, 8)];
  const dirs: [number, number][] = [[0, -1], [1, 0], [0, 1], [-1, 0]];
  dirs.forEach(([dx, dy]) => els.push(ln(x + dx * 10, y + dy * 10, x + dx * r, y + dy * r, C.gray)));
  return els;
};
